import React, { useState } from 'react';
import { Button, Tooltip, OverlayTrigger } from 'react-bootstrap';
import { useFavorites } from '../../contexts/FavoritesContext';

const FavoritesButton = ({ 
  type, // 'vendor', 'search', 'package'
  item,
  size = 'sm',
  variant = 'outline-warning',
  showText = false,
  className = ''
}) => {
  const { 
    isVendorFavorite, 
    isSearchFavorite, 
    isPackageFavorite,
    addFavoriteVendor,
    addFavoriteSearch,
    addFavoritePackage,
    removeFavoriteVendor,
    removeFavoriteSearch,
    removeFavoritePackage
  } = useFavorites();

  const [isLoading, setIsLoading] = useState(false);

  const isFavorite = () => {
    switch (type) {
      case 'vendor': return isVendorFavorite(item.id);
      case 'search': return isSearchFavorite(item.id);
      case 'package': return isPackageFavorite(item.id);
      default: return false;
    }
  };

  const handleToggleFavorite = async () => {
    setIsLoading(true);
    
    try {
      if (isFavorite()) {
        // Remove from favorites
        switch (type) {
          case 'vendor':
            removeFavoriteVendor(item.id);
            break;
          case 'search':
            removeFavoriteSearch(item.id);
            break;
          case 'package':
            removeFavoritePackage(item.id);
            break;
        }
      } else {
        // Add to favorites
        const favoriteItem = {
          ...item,
          favoriteId: Date.now(),
          addedAt: new Date().toISOString(),
          type
        };

        switch (type) {
          case 'vendor':
            addFavoriteVendor(favoriteItem);
            break;
          case 'search':
            addFavoriteSearch(favoriteItem);
            break;
          case 'package':
            addFavoritePackage(favoriteItem);
            break;
        }
      }
    } catch (error) {
      console.error('Error toggling favorite:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const tooltipText = isFavorite() 
    ? `Hapus dari favorit` 
    : `Tambahkan ke favorit`;

  const buttonText = showText 
    ? (isFavorite() ? 'Favorited' : 'Add to Favorites')
    : '';

  return (
    <OverlayTrigger
      placement="top"
      overlay={<Tooltip>{tooltipText}</Tooltip>}
    >
      <Button
        variant={isFavorite() ? 'warning' : variant}
        size={size}
        onClick={handleToggleFavorite}
        disabled={isLoading}
        className={className}
      >
        {isLoading ? (
          <span className="spinner-border spinner-border-sm" role="status" aria-hidden="true"></span>
        ) : (
          <>
            <i className={`fas fa-${isFavorite() ? 'star' : 'star'} ${isFavorite() ? 'text-white' : ''}`}></i>
            {showText && <span className="ms-1">{buttonText}</span>}
          </>
        )}
      </Button>
    </OverlayTrigger>
  );
};

export default FavoritesButton;