import React, { useState, useEffect } from 'react';
import { 
  Container, Row, Col, Card, Form, 
  Alert, Table, Badge, Spinner 
} from 'react-bootstrap';
import { useSearchParams, useNavigate } from 'react-router-dom';
import { useNotification } from '../contexts/NotificationContext';
import { useSearch } from '../contexts/SearchContext';
import FavoritesButton from '../components/common/FavoritesButton';

const VendorSearchPage = () => {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const { showNotification } = useNotification();
  const { addToHistory } = useSearch();
  
  const [vendorName, setVendorName] = useState(searchParams.get('q') || '');
  const [tahun, setTahun] = useState('2026');
  const [mode, setMode] = useState('pu');
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState([]);
  const [stats, setStats] = useState({ total: 0, totalValue: 0 });

  // Handle search from URL
  useEffect(() => {
    const query = searchParams.get('q');
    if (query) {
      setVendorName(query);
      handleSearch(query);
    }
  }, [searchParams]);

  const handleSearch = async (customVendor = null) => {
    const searchVendor = customVendor || vendorName;
    
    if (!searchVendor.trim()) {
      showNotification('Masukkan nama vendor terlebih dahulu', 'warning');
      return;
    }

    setLoading(true);
    
    // Add to search history
    addToHistory({
      type: 'vendor',
      query: searchVendor,
      timestamp: new Date().toISOString()
    });

    try {
      // Call backend API
      const response = await fetch(
        `http://localhost:5000/api/search/vendor?vendor=${encodeURIComponent(searchVendor)}&tahun=${tahun}&mode=${mode}`
      );
      
      const data = await response.json();
      
      if (data.status === 'success') {
        setResults(data.data);
        calculateStats(data.data);
        showNotification(`Ditemukan ${data.total} tender untuk ${searchVendor}`, 'success');
      } else {
        showNotification(data.message, 'error');
        setResults([]);
      }
    } catch (error) {
      console.error('Search error:', error);
      showNotification('Gagal menghubungi backend', 'error');
      
      // Fallback demo data
      setResults(generateDemoData(searchVendor));
      showNotification('Menampilkan data demo', 'info');
    } finally {
      setLoading(false);
    }
  };

  const calculateStats = (data) => {
    const total = data.length;
    let totalValue = 0;
    
    // Parse nilai pagu dari string seperti "Rp 1.5 M" atau "Rp 500 Juta"
    data.forEach(item => {
      const pagu = item.nilai_pagu || item.pagu || '';
      if (pagu.includes('M')) {
        const value = parseFloat(pagu.replace(/[^\d.]/g, '')) * 1000000000;
        totalValue += value;
      } else if (pagu.includes('Juta')) {
        const value = parseFloat(pagu.replace(/[^\d.]/g, '')) * 1000000;
        totalValue += value;
      } else if (pagu.includes('T')) {
        const value = parseFloat(pagu.replace(/[^\d.]/g, '')) * 1000000000000;
        totalValue += value;
      }
    });
    
    setStats({ total, totalValue });
  };

  const generateDemoData = (vendor) => {
    return [
      {
        no: 1,
        kode_tender: `PU-${tahun}-001`,
        nama_paket: `Pembangunan Jalan Tol Trans Jawa Tahun ${tahun}`,
        nama_pemenang: `PT ${vendor} Tbk`,
        nilai_pagu: 'Rp 2.5 T',
        tanggal: `15 Januari ${tahun}`,
        tahun: tahun,
        lpse: 'pu',
        lpse_nama: 'Kementerian PU',
        satuan_kerja: 'Ditjen Bina Marga',
        url_detail: `https://spse.inaproc.id/pu/lelang/PU-${tahun}-001/pengumumanlelang`,
        confidence: 'demo'
      },
      {
        no: 2,
        kode_tender: `PU-${tahun}-002`,
        nama_paket: `Pembangunan Gedung Perkantoran Tahun ${tahun}`,
        nama_pemenang: `PT ${vendor}`,
        nilai_pagu: 'Rp 350 M',
        tanggal: `10 Februari ${tahun}`,
        tahun: tahun,
        lpse: 'pu',
        lpse_nama: 'Kementerian PU',
        satuan_kerja: 'Ditjen Cipta Karya',
        url_detail: `https://spse.inaproc.id/pu/lelang/PU-${tahun}-002/pengumumanlelang`,
        confidence: 'demo'
      }
    ];
  };

  const handleExport = async () => {
    try {
      const response = await fetch(
        `http://localhost:5000/api/export/csv?type=vendor&vendor=${encodeURIComponent(vendorName)}&tahun=${tahun}&mode=${mode}`,
        { method: 'GET' }
      );
      
      if (response.ok) {
        const blob = await response.blob();
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `vendor-${vendorName}-${tahun}.csv`;
        document.body.appendChild(a);
        a.click();
        a.remove();
        showNotification('Data berhasil diexport', 'success');
      }
    } catch (error) {
      showNotification('Gagal mengexport data', 'error');
    }
  };

  const formatCurrency = (value) => {
    if (value >= 1000000000000) {
      return `Rp ${(value / 1000000000000).toFixed(2)} T`;
    } else if (value >= 1000000000) {
      return `Rp ${(value / 1000000000).toFixed(2)} M`;
    } else if (value >= 1000000) {
      return `Rp ${(value / 1000000).toFixed(2)} Juta`;
    }
    return `Rp ${value.toLocaleString()}`;
  };

  return (
    <Container className="py-4">
      <Row className="mb-4">
        <Col>
          <h1 className="display-6 fw-bold">
            <i className="fas fa-building me-2"></i>
            Pencarian Vendor/Rekanan
          </h1>
          <p className="text-muted">
            Cari data tender berdasarkan nama perusahaan/penyedia
          </p>
        </Col>
      </Row>

      {/* Search Form */}
      <Row className="mb-4">
        <Col lg={8}>
          <Card className="shadow-sm">
            <Card.Body>
              <Form onSubmit={(e) => { e.preventDefault(); handleSearch(); }}>
                <Row>
                  <Col md={5}>
                    <Form.Group className="mb-3">
                      <Form.Label>
                        <i className="fas fa-building me-1"></i>
                        Nama Vendor
                      </Form.Label>
                      <Form.Control
                        type="text"
                        placeholder="Contoh: Adhi Karya, Waskita, dll"
                        value={vendorName}
                        onChange={(e) => setVendorName(e.target.value)}
                        disabled={loading}
                      />
                    </Form.Group>
                  </Col>
                  <Col md={3}>
                    <Form.Group className="mb-3">
                      <Form.Label>
                        <i className="fas fa-calendar me-1"></i>
                        Tahun
                      </Form.Label>
                      <Form.Select
                        value={tahun}
                        onChange={(e) => setTahun(e.target.value)}
                        disabled={loading}
                      >
                        <option value="2023">2023</option>
                        <option value="2024">2024</option>
                        <option value="2025">2025</option>
                        <option value="2026">2026</option>
                      </Form.Select>
                    </Form.Group>
                  </Col>
                  <Col md={3}>
                    <Form.Group className="mb-3">
                      <Form.Label>
                        <i className="fas fa-filter me-1"></i>
                        Mode Pencarian
                      </Form.Label>
                      <Form.Select
                        value={mode}
                        onChange={(e) => setMode(e.target.value)}
                        disabled={loading}
                      >
                        <option value="pu">Kementerian PU</option>
                        <option value="kementerian">Semua Kementerian</option>
                        <option value="provinsi_jawa">Provinsi Jawa</option>
                        <option value="nasional">Nasional</option>
                      </Form.Select>
                    </Form.Group>
                  </Col>
                  <Col md={1} className="d-flex align-items-end">
                    <button
                      type="submit"
                      className="btn btn-primary w-100"
                      disabled={loading || !vendorName.trim()}
                    >
                      {loading ? (
                        <Spinner animation="border" size="sm" />
                      ) : (
                        <i className="fas fa-search"></i>
                      )}
                    </button>
                  </Col>
                </Row>
              </Form>
            </Card.Body>
          </Card>
        </Col>
        <Col lg={4}>
          <Card className="shadow-sm h-100">
            <Card.Body className="d-flex flex-column">
              <h6 className="card-title">
                <i className="fas fa-chart-bar me-1"></i>
                Statistik
              </h6>
              <div className="mt-auto">
                <div className="d-flex justify-content-between mb-2">
                  <span className="text-muted">Total Tender:</span>
                  <Badge bg="info">{stats.total}</Badge>
                </div>
                <div className="d-flex justify-content-between">
                  <span className="text-muted">Nilai Total:</span>
                  <Badge bg="success">{formatCurrency(stats.totalValue)}</Badge>
                </div>
              </div>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Results */}
      {results.length > 0 && (
        <Row className="mb-4">
          <Col>
            <Card className="shadow-sm">
              <Card.Header className="bg-light d-flex justify-content-between align-items-center">
                <div>
                  <i className="fas fa-list me-2"></i>
                  Hasil Pencarian ({results.length} tender)
                </div>
                <div>
                  <button
                    className="btn btn-success btn-sm"
                    onClick={handleExport}
                    disabled={results.length === 0}
                  >
                    <i className="fas fa-download me-1"></i>
                    Export CSV
                  </button>
                </div>
              </Card.Header>
              <Card.Body className="p-0">
                <Table responsive hover className="mb-0">
                  <thead className="table-light">
                    <tr>
                      <th>No</th>
                      <th>LPSE</th>
                      <th>Kode Tender</th>
                      <th>Nama Paket</th>
                      <th>Nama Pemenang</th>
                      <th>Nilai Pagu</th>
                      <th>Tanggal</th>
                      <th>Satuan Kerja</th>
                      <th>Aksi</th>
                    </tr>
                  </thead>
                  <tbody>
                    {results.map((item, index) => (
                      <tr key={index}>
                        <td>{item.no || index + 1}</td>
                        <td>
                          <Badge bg="primary">{item.lpse_nama}</Badge>
                        </td>
                        <td>
                          <code>{item.kode_tender}</code>
                        </td>
                        <td>
                          <strong>{item.nama_paket}</strong>
                        </td>
                        <td>
                          <Badge bg="success">{item.nama_pemenang}</Badge>
                        </td>
                        <td>
                          <Badge bg="warning">{item.nilai_pagu || item.pagu}</Badge>
                        </td>
                        <td>{item.tanggal}</td>
                        <td>
                          <small className="text-muted">{item.satuan_kerja}</small>
                        </td>
                        <td>
                          <button
                            className="btn btn-outline-primary btn-sm"
                            onClick={() => window.open(item.url_detail, '_blank')}
                            title="Lihat detail di SPSE"
                          >
                            <i className="fas fa-external-link-alt"></i>
                          </button>
                          <FavoritesButton 
                            type="vendor"
                            item={{
                              id: item.kode_tender,
                              name: item.nama_pemenang,
                              package: item.nama_paket,
                              value: item.nilai_pagu,
                              date: item.tanggal,
                              lpse: item.lpse_nama
                            }}
                            size="sm"
                          />
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </Table>
              </Card.Body>
              {results[0]?.confidence === 'demo' && (
                <Card.Footer className="bg-warning bg-opacity-10">
                  <div className="text-warning">
                    <i className="fas fa-exclamation-triangle me-2"></i>
                    Data demo - Gunakan untuk testing
                  </div>
                </Card.Footer>
              )}
            </Card>
          </Col>
        </Row>
      )}

      {/* Empty State */}
      {!loading && results.length === 0 && vendorName && (
        <Row>
          <Col>
            <Alert variant="info" className="text-center">
              <i className="fas fa-info-circle fa-2x mb-3"></i>
              <h5>Tidak ada data ditemukan</h5>
              <p>Coba dengan nama vendor lain atau tahun yang berbeda</p>
            </Alert>
          </Col>
        </Row>
      )}

      {/* Tips */}
      <Row className="mt-4">
        <Col>
          <Card className="shadow-sm">
            <Card.Header className="bg-light">
              <i className="fas fa-lightbulb me-2"></i>
              Tips Pencarian Vendor
            </Card.Header>
            <Card.Body>
              <Row>
                <Col md={4}>
                  <div className="d-flex mb-3">
                    <div className="flex-shrink-0">
                      <i className="fas fa-search text-primary"></i>
                    </div>
                    <div className="flex-grow-1 ms-3">
                      <h6>Nama Lengkap</h6>
                      <p className="small text-muted mb-0">
                        Gunakan nama lengkap perusahaan untuk hasil terbaik
                      </p>
                    </div>
                  </div>
                </Col>
                <Col md={4}>
                  <div className="d-flex mb-3">
                    <div className="flex-shrink-0">
                      <i className="fas fa-filter text-success"></i>
                    </div>
                    <div className="flex-grow-1 ms-3">
                      <h6>Filter Tahun</h6>
                      <p className="small text-muted mb-0">
                        Pilih tahun 2026 untuk data terbaru
                      </p>
                    </div>
                  </div>
                </Col>
                <Col md={4}>
                  <div className="d-flex mb-3">
                    <div className="flex-shrink-0">
                      <i className="fas fa-download text-warning"></i>
                    </div>
                    <div className="flex-grow-1 ms-3">
                      <h6>Export Data</h6>
                      <p className="small text-muted mb-0">
                        Export hasil ke CSV untuk analisis lanjutan
                      </p>
                    </div>
                  </div>
                </Col>
              </Row>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default VendorSearchPage;